import json,statistics,datetime
from pathlib import Path
root=Path(__file__).parent
records=[json.loads(p.read_text()) for p in (root/'tests/timings-paired').glob('*/result.json')]
run=json.loads((root/'tests/timing-paired-run.json').read_text())
lines=['# Equivalent Python and JavaScript support check comparison','','## Workload and conditions','',f"Hosted run 45875517420, source {run['headSha']}. Two independent ubuntu-24.04 jobs, each running both runtimes on the exact same host/image and fixture bytes. Runtime order is reversed in the second job. Two paired replicas per runtime. Each sample launches five independent helper processes: tool, output, provenance, candidate metadata and trusted Review. Each replica records one first-process batch and ten repeated batches. Cold means first invocation in a fresh job, not proof of a cold physical host. Warm means repeated invocation with filesystem caches, not a persistent interpreter. Only the shared valid-input domain is timed; stricter missing-input behavior is tested separately.",'','## Observed timings','']
summary={}
for runtime in ['javascript','python']:
 selected=[r for r in records if r['runtime']==runtime];cold=[s['milliseconds'] for r in selected for s in r['samples'] if s['phase']=='cold-first-process'];warm=[s['milliseconds'] for r in selected for s in r['samples'] if s['phase']=='warm-repeat'];versions=sorted({r['version'] for r in selected});images=sorted({r['image_version'] for r in selected})
 summary[runtime]={'cold_n':len(cold),'cold_median_ms':statistics.median(cold),'warm_n':len(warm),'warm_median_ms':statistics.median(warm),'warm_min_ms':min(warm),'warm_max_ms':max(warm),'versions':versions,'images':images}
 lines += [f"{runtime}: {', '.join(versions)} on image {', '.join(images)}. First-invocation n={len(cold)}, median {statistics.median(cold):.2f} ms per five-check batch. Repeated n={len(warm)}, median {statistics.median(warm):.2f} ms, range {min(warm):.2f}–{max(warm):.2f} ms.",'']
for job in run['jobs']:
 def seconds(a,b):return (datetime.datetime.fromisoformat(b.replace('Z','+00:00'))-datetime.datetime.fromisoformat(a.replace('Z','+00:00'))).total_seconds()
 setup=next(s for s in job['steps'] if s['name']=='Measure runtime setup availability');checks=[s for s in job['steps'] if s['name'] in ['Execute first runtime','Execute second runtime']]
 lines += [f"{job['name']}: runtime-availability step {seconds(setup['startedAt'],setup['completedAt']):.0f}s, both measurement steps {sum(seconds(c['startedAt'],c['completedAt']) for c in checks):.0f}s total, total job {seconds(job['startedAt'],job['completedAt']):.0f}s. API timestamps have one-second granularity. No runtime installation step occurred.",'']
lines += [f"Overall comparison workflow elapsed {seconds(run['createdAt'],run['updatedAt']):.0f}s, including scheduling and both paired jobs. This is shared experiment wall time, not a per-language native pipeline result.",'','## Simplicity and maintenance','',"The five JavaScript guards require zero package dependencies, zero npm installs and zero setup-node steps. GitHub supplies Node24 for native JavaScript actions. Python was already installed in the benchmark runner; no Python installation cost or avoided installation time is claimed. The old helpers use the Python standard library and shell invocation; their explicit setup cost on this image was also zero. JavaScript improves action discoverability, typed workflow input boundaries and one shared failure implementation, but adds metadata and entrypoint files that must remain synchronized. Neither language makes receipt authenticity or trusted-source selection automatic.",'',"Measured helper timings cover subprocess startup, reading, parsing and hashing small files. Two paired independent hosts and twenty repeated batches cannot establish production tail latency, full pipeline speedup or a causal host-cache effect. JavaScript should be chosen for the Python-free reusable-action requirement, not an assumed speed advantage. The separate actual native qualification is functional evidence, not a controlled timing comparison against E.18's full pipeline."]
(root/'comparison_report.md').write_text('\n'.join(lines)+'\n');(root/'tests/comparison-summary.json').write_text(json.dumps(summary,indent=2))
print('\n'.join(lines[8:13]))

with (root/'comparison_report.md').open('a') as f:f.write('\n## Rejected exploratory comparison\n\nEarlier five-check run 45875048579 used different runner image revisions across runtime groups during a hosted-image rollout. It is retained under tests/timings-five but excluded from the accepted comparison. Corrected run 45875517420 pairs both runtimes on each host and counterbalances order. This controls the within-pair image difference, while background load and provider physical-host warmth remain uncontrolled.\n')
